S=/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/415b1f78-7053-478a-bd65-26960f3ce684/scratchpad && cat > $S/gutter-probe.mjs <<'EOF'
const QUERIES = ["evidence color", "discourse tool keyboard", "left sidebar", "default sort", "disable sidebar open", "suggestive", "page format"];
export default {
  async ready({ page }) { return page.locator("input[placeholder='Search settings']").isVisible(); },
  async run({ page, outDir }) {
    const input = page.locator("input[placeholder='Search settings']");
    const out = {};
    for (const q of QUERIES) {
      await input.fill(q);
      await page.waitForTimeout(300);
      const first = page.locator(".bp3-menu .bp3-menu-item").first();
      if (!(await first.count())) { out[q] = "no result"; continue; }
      const label = (await first.innerText()).split("\n")[0];
      await first.click();
      await page.waitForTimeout(200);
      out[q] = await page.evaluate((label) => {
        const row = document.querySelector(".bg-gray-100.-mx-2");
        if (!row) return { label, err: "no flash" };
        const r = row.getBoundingClientRect();
        let L = -1e9, R = 1e9, clipper = null;
        for (let el = row.parentElement; el; el = el.parentElement) {
          const cs = getComputedStyle(el);
          if (cs.overflowX !== "visible") { const c = el.getBoundingClientRect(); if (c.left > L) { L = c.left; clipper = el.className; } R = Math.min(R, c.right); }
        }
        const pl = parseFloat(getComputedStyle(row).paddingLeft);
        return { label, visibleLeftGutter: +(Math.min(pl, pl - (Math.max(L, r.left) - r.left))).toFixed(1), visibleRightGutter: +(pl - (r.right - Math.min(R, r.right))).toFixed(1), clipper: String(clipper).slice(0, 60) };
      }, label);
      await page.waitForTimeout(1400);
    }
    return out;
  },
};
EOF
